use std::process::Command;

#[test]
fn format_workspace_once_then_remove_harness() {
    let status = Command::new("cargo").args(["fmt", "--all"]).status().expect("run cargo fmt");
    assert!(status.success());
    std::fs::remove_file("crates/zero3-core/tests/format_node_desktop_once.rs").expect("remove formatter harness");
}
